```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    int liczbaPlateau = 0;
    int lacznaDlugosc = 0;
    int curDl = 1;

    for (int i = 1; i < n; i++) {
        if (T[i] == T[i - 1]) {
            curDl++;
        } else {
            if (curDl >= 2) {
                liczbaPlateau++;
                lacznaDlugosc += curDl;
            }
            curDl = 1;
        }
    }
    // Sprawdzenie ostatniego fragmentu
    if (curDl >= 2) {
        liczbaPlateau++;
        lacznaDlugosc += curDl;
    }

    cout << "Liczba plateau: " << liczbaPlateau << endl;
    cout << "Laczna dlugosc: " << lacznaDlugosc << endl;
    return 0;
}
```

**Wyjasnienie**: Skanowanie liniowe z licznikiem biezacej serii rownych elementow. Gdy seria sie konczy (lub koniec tablicy), jesli dlugosc >= 2 to mamy plateau.

Weryfikacja:
- 3,3,3 (dl.3) -> plateau 1, laczna=3
- 5 (dl.1) -> nie
- 7,7 (dl.2) -> plateau 2, laczna=5
- 2 (dl.1) -> nie
- 1,1,1,1 (dl.4) -> plateau 3, laczna=9
- 4,4 (dl.2) -> plateau 4, laczna=11
- 6 (dl.1) -> nie
- 8,8 (dl.2) -> plateau 5, laczna=13
- 9,9,9 (dl.3) -> plateau 6, laczna=16
- 5 (dl.1) -> nie
